cd /user/user1/autorlbench-runs/20261118222027-48496-4d5b/workspace
python3 -I - <<'EOF'
import json, collections
rows=[json.loads(l) for l in open('corpus/manifest.jsonl')]
print('=== per instance ===')
for r in rows:
    f2p,p2p=r['fail_to_pass'],r['pass_to_pass']
    print(f"{r['instance_id']:60s} f2p={len(f2p):3d} p2p={len(p2p):3d} extra={r['extra_args']}")
print()
print('=== non-.py required nodes ===')
for r in rows:
    for kind in ('fail_to_pass','pass_to_pass'):
        for n in r[kind]:
            if not n.split('::')[0].endswith('.py'):
                print(r['instance_id'],kind,n)
print()
print('=== tests.md count ===')
c=sum(1 for r in rows for k in ('fail_to_pass','pass_to_pass') if 'tests.md::tests.md' in r[k])
print(c)
print('=== duplicate normalized names across different files within an instance ===')
def norm(n): return '.'.join(n.split('::')[1:])
for r in rows:
    req=list(dict.fromkeys(r['fail_to_pass']+r['pass_to_pass']))
    by=collections.defaultdict(set)
    for n in req: by[norm(n)].add(n.split('::')[0])
    dup={k:v for k,v in by.items() if len(v)>1}
    if dup: print(r['instance_id'], dict(list(dup.items())[:5]))
print('=== metadata ===')
print(rows[0]['metadata'])
EOF

