rows=[json.loads(l) for l in open('logs/historical/pass_a/regrade.jsonl')]
def cls(rid):
    p='corpus/submissions/'+rid+'.patch'
    if not os.path.exists(p): return 'MISSING'
    t=open(p,encoding='utf-8',errors='replace').read()
    if not t.strip(): return 'empty-patch'
    if len(t)<100 and t.startswith('Error'): return 'error-stub'
    kinds=[]
    if 'b/pytest.ini' in t: kinds.append('pytest.ini')
    if 'b/conftest.py' in t: kinds.append('conftest')
    if 'while True' in t: kinds.append('hang')
    if 'b/voluptuous/tests/tests.py' in t or 'b/tests/codec' in t and '-def test' in t: kinds.append('exam-edit')
    return '+'.join(kinds) or 'code'
from collections import Counter, defaultdict
c=Counter(); ex=defaultdict(list)
for r in rows:
    k=cls(r['record_id']); c[k]+=1
    if len(ex[k])<3: ex[k].append(r['record_id'])
for k,v in c.most_common():
    print(f'{k:20s} {v:4d}  e.g. {ex[k][0]}')
EOF

