import json, os, collections
rows={json.loads(l)['record_id']:json.loads(l) for l in open('logs/historical/pass_a/regrade.jsonl')}
def cls(rid):
    p='corpus/submissions/'+rid+'.patch'
    t=open(p,encoding='utf-8',errors='replace').read()
    k=[]
    if 'b/pytest.ini' in t: k.append('pytest.ini')
    if 'b/conftest.py' in t: k.append('conftest')
    return '+'.join(k) or 'clean'
tab=collections.defaultdict(collections.Counter)
for rid,r in rows.items():
    ex=[n for n in r['notes'] if n.startswith('exit=')][0]
    tab[cls(rid)][ex]+=1
for k,v in tab.items(): print(f'{k:12s}',dict(v))
print()
print('=== pytest.ini-class records: per-instance exit codes ===')
for rid,r in sorted(rows.items()):
    if cls(rid)=='pytest.ini':
        ex=[n for n in r['notes'] if n.startswith('exit=')][0]
        print(f'  {rid:70s} {ex}')
EOF

